const items = $input.all();
const cleanedData = items.map((item) => {
  const cleanedItem = { ...item.json };
  // Remove unnecessary characters from Sales_Rep
  cleanedItem.Sales_Rep = cleanedItem.Sales_Rep.replace(/[^a-zA-Z ]/g, "");
  // Convert Sale_Date to Date object
  cleanedItem.Sale_Date = new Date(cleanedItem.Sale_Date);
  // Split Region_and_Sales_Rep into separate fields
  const [Region, Sales_Rep] = cleanedItem.Region_and_Sales_Rep.split(" and ");
  cleanedItem.Region = Region;
  cleanedItem.Sales_Rep = Sales_Rep;
  // Remove the combined field
  delete cleanedItem.Region_and_Sales_Rep;
  return { json: cleanedItem };
});
return cleanedData;

const items = $input.all();

// =======================
// MASTER TOTALS
// =======================
let totalRevenue = 0;
let totalOrders = 0;
let totalQuantity = 0;
let totalProfit = 0; // ✅ ADDED

// =======================
// AGGREGATORS
// =======================
const revenueByRegion = {};
const revenueByProductCategory = {};
const ordersByPaymentMethod = {};
const revenueBySalesChannel = {};
const ordersByDate = {};

// =======================
// PROCESS ROWS
// =======================
items.forEach(item => {
  const row = item.json;

  const revenue = parseFloat(row.Sales_Amount) || 0;
  const quantity = parseFloat(row.Quantity_Sold) || 0;

  const unitPrice = parseFloat(row.Unit_Price) || 0;   // ✅ ADDED
  const unitCost = parseFloat(row.Unit_Cost) || 0;     // ✅ ADDED
  const profit = (unitPrice - unitCost) * quantity;    // ✅ ADDED

  const region = row.Region || "Unknown";
  const category = row.Product_Category || "Unknown";
  const paymentMethod = row.Payment_Method || "Unknown";
  const salesChannel = row.Sales_Channel || "Unknown";
  const date = row.Sale_Date ? row.Sale_Date.split("T")[0] : "Unknown";

  // ---------- Totals ----------
  totalRevenue += revenue;
  totalOrders += 1;
  totalQuantity += quantity;
  totalProfit += profit; // ✅ ADDED

  // ---------- Revenue by Region ----------
  revenueByRegion[region] =
    (revenueByRegion[region] || 0) + revenue;

  // ---------- Revenue by Product Category ----------
  revenueByProductCategory[category] =
    (revenueByProductCategory[category] || 0) + revenue;

  // ---------- Orders by Payment Method ----------
  ordersByPaymentMethod[paymentMethod] =
    (ordersByPaymentMethod[paymentMethod] || 0) + 1;

  // ---------- Revenue by Sales Channel ----------
  revenueBySalesChannel[salesChannel] =
    (revenueBySalesChannel[salesChannel] || 0) + revenue;

  // ---------- Orders by Date ----------
  ordersByDate[date] =
    (ordersByDate[date] || 0) + 1;
});

// =======================
// HELPER: TOP CONTRIBUTOR
// =======================
const getTop = (obj) =>
  Object.entries(obj).sort((a, b) => b[1] - a[1])[0];

// =======================
// DERIVED KPIs
// =======================
const avgOrderValue = totalRevenue / totalOrders;
const avgQuantityPerOrder = totalQuantity / totalOrders;

const topRegion = getTop(revenueByRegion);
const topCategory = getTop(revenueByProductCategory);
const topChannel = getTop(revenueBySalesChannel);

// =======================
// FINAL OUTPUT
// =======================
return [
  {
    json: {
      // -------- KPI CARDS --------
      totalRevenue: Number(totalRevenue.toFixed(2)),
      totalProfit: Number(totalProfit.toFixed(2)), // ✅ ADDED
      totalOrders,
      totalQuantitySold: Number(totalQuantity.toFixed(2)),
      averageOrderValue: Number(avgOrderValue.toFixed(2)),
      averageQuantityPerOrder: Number(avgQuantityPerOrder.toFixed(2)),

      // -------- TOP CONTRIBUTORS --------
      topRegionByRevenue: {
        region: topRegion[0],
        revenue: Number(topRegion[1].toFixed(2)),
        percentageOfTotalRevenue: Number(
          ((topRegion[1] / totalRevenue) * 100).toFixed(2)
        ),
      },

      topCategoryByRevenue: {
        category: topCategory[0],
        revenue: Number(topCategory[1].toFixed(2)),
        percentageOfTotalRevenue: Number(
          ((topCategory[1] / totalRevenue) * 100).toFixed(2)
        ),
      },

      topSalesChannelByRevenue: {
        channel: topChannel[0],
        revenue: Number(topChannel[1].toFixed(2)),
        percentageOfTotalRevenue: Number(
          ((topChannel[1] / totalRevenue) * 100).toFixed(2)
        ),
      },

      // -------- CHART DATA --------
      revenueByRegion,
      revenueByProductCategory,
      ordersByPaymentMethod,
      revenueBySalesChannel,
      ordersByDate,

      // -------- DATA QUALITY --------
      numberOfUniqueRegions: Object.keys(revenueByRegion).length,
      numberOfUniqueCategories: Object.keys(revenueByProductCategory).length,
      numberOfPaymentMethods: Object.keys(ordersByPaymentMethod).length,
    },
  },
];

const kpi = $input.first().json;

// -------------------------------
// Helper: Build Chart.js config
// -------------------------------
const buildChart = (type, title, labels, data) => ({
  type,
  data: {
    labels,
    datasets: [
      {
        label: title,
        data,
        backgroundColor: [
          "#4F46E5",
          "#22C55E",
          "#F97316",
          "#EF4444",
          "#06B6D4",
          "#8B5CF6",
          "#EC4899"
        ],
        borderWidth: 1,
        fill: false
      }
    ]
  },
  options: {
    responsive: true,
    plugins: {
      title: {
        display: true,
        text: title,
        font: { size: 16 }
      },
      legend: {
        display: type !== "bar"
      }
    },
    scales: type === "bar" || type === "line"
      ? { y: { beginAtZero: true } }
      : {}
  }
});

// -------------------------------
// Helper: Convert chart → URL
// -------------------------------
const toQuickChartUrl = (chartConfig) =>
  "https://quickchart.io/chart?c=" +
  encodeURIComponent(JSON.stringify(chartConfig));

// -------------------------------
// Chart 1: Revenue by Category
// -------------------------------
const revenueByCategory = buildChart(
  "bar",
  "Revenue by Product Category",
  Object.keys(kpi.revenueByProductCategory),
  Object.values(kpi.revenueByProductCategory)
);

// -------------------------------
// Chart 2: Orders by Payment Method
// -------------------------------
const ordersByPaymentMethod = buildChart(
  "pie",
  "Orders by Payment Method",
  Object.keys(kpi.ordersByPaymentMethod),
  Object.values(kpi.ordersByPaymentMethod)
);

// -------------------------------
// Chart 3: Revenue by Sales Channel
// -------------------------------
const revenueBySalesChannel = buildChart(
  "bar",
  "Revenue by Sales Channel",
  Object.keys(kpi.revenueBySalesChannel),
  Object.values(kpi.revenueBySalesChannel)
);

// -------------------------------
// Chart 4: Orders by Date (FIXED)
// -------------------------------
const sortedDates = Object.keys(kpi.ordersByDate).sort();
const sortedOrderCounts = sortedDates.map(
  d => kpi.ordersByDate[d]
);

const ordersByDate = buildChart(
  "line",
  "Orders by Date",
  sortedDates,
  sortedOrderCounts
);

// -------------------------------
// FINAL OUTPUT (URLs)
// -------------------------------
return [
  {
    json: {
      chartUrls: {
        revenueByCategory: toQuickChartUrl(revenueByCategory),
        ordersByPaymentMethod: toQuickChartUrl(ordersByPaymentMethod),
        revenueBySalesChannel: toQuickChartUrl(revenueBySalesChannel),
        ordersByDate: toQuickChartUrl(ordersByDate)
      }
    }
  }
];
